WorkflowProcessEvent.eventDescription:
function servicetask130(attempt, message) {

    var codColigada = hAPI.getCardValue("CodColigada");
    var codFilial = hAPI.getCardValue("filial") || "1";
    var idprd = hAPI.getCardValue("IDPRD");
    var codigoCliente = hAPI.getCardValue("codigo_cliente");
    var idmovMovimento02 = hAPI.getCardValue("idmov2");
    var coligadaCliente = hAPI.getCardValue("coligadaCliente") || "0";

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");

    var indexIrrfCadastro = hAPI.getCardValue("indexIrrCadastro");
    var indexInssCadastro = hAPI.getCardValue("indexInssCadastro");

    var contexto = "CODCOLIGADA=" + codColigada + ";CODFILIAL=" + codFilial + ";CODSISTEMA=T;CODUSUARIO=fluig";

    var codigoIrrfCliente = "";
    var codigoInssCliente = "";

    log.info("[G12-CadastrarIRRFeINSS] Iniciando - CODCOLIGADA=" + codColigada);


    function criarClienteRM() {
        var servico = ServiceManager.getService("wsDataServer");
        var instancia = servico.instantiate("com.totvs.WsDataServer");
        var ws = instancia.getRMIwsDataServer();

        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        return servico.getCustomClient(ws, properties, []);
    }


    if (indexIrrfCadastro != "" && indexIrrfCadastro != null && indexIrrfCadastro != "undefined") {
        log.warn("[G12-CADASTRO-DE-NOVO-IRRF] Iniciada integracao de cadastro de IRRF");

        for (var index = 1; index <= indexIrrfCadastro; index++) {
            var codigoIrrf = hAPI.getCardValue("codigoIrrfCadastro___" + index);
            var descricaoIrrf = hAPI.getCardValue("descricaoIrrfCadastro___" + index);
            var aliquotaIrrf = hAPI.getCardValue("aliquotaIrrfCadastro___" + index);
            var codigoOficial = hAPI.getCardValue("codOficialIrrfCadastro___" + index);
            var aplicavelA = hAPI.getCardValue("aplicavelA___" + index);


            if (!codigoIrrf) {
                continue;
            }

            codigoIrrfCliente = codigoIrrf; 

            log.info("CODIGO IRRF PARA CADASTRO -> " + codigoIrrf);
            log.info("DESCRICAO IRRF PARA CADASTRO -> " + descricaoIrrf);
            log.info("ALIQUOTA IRRF PARA CADASTRO -> " + aliquotaIrrf);
            log.info("CODIGO OFICIAL IRRF PARA CADASTRO -> " + codigoOficial);
            log.info("APLICAVEL A IRRF PARA CADASTRO -> " + aplicavelA);

            try {
                var authService = criarClienteRM();


                var xmlIrrf =
                    "<FinIRRF>" +
                    "<FIRRF>" +
                    "<CODRECEITA>" + codigoIrrf + "</CODRECEITA>" +
                    "<DESCRICAO>" + descricaoIrrf + "</DESCRICAO>" +
                    "<ALIQUOTA>" + aliquotaIrrf + "</ALIQUOTA>" +
                    "<PESSOAFISOUJUR>" + aplicavelA + "</PESSOAFISOUJUR>" +
                    "<CODRECEITAOFICIAL>" + codigoOficial + "</CODRECEITAOFICIAL>" +
                    "</FIRRF>" +
                    "</FinIRRF>";

                var resultado = authService.saveRecord("FinIRRFData", xmlIrrf, contexto);
                log.info("[G12-CADASTRO-DE-NOVO-IRRF] Resultado: " + resultado);

            } catch (e) {
                log.error("[G12-CADASTRO-DE-NOVO-IRRF] Erro: " + String(e));
                throw e;
            }
        }
    }


    if (indexInssCadastro != "" && indexInssCadastro != null && indexInssCadastro != "undefined") {
        log.warn("[G12-CADASTRO-DE-NOVO-INSS] Iniciada integracao de cadastro de INSS");

        for (var index = 1; index <= indexInssCadastro; index++) {
            var codigoInss = hAPI.getCardValue("codigoInssCadastro___" + index);
            var descricaoInss = hAPI.getCardValue("descricaoInssCadastro___" + index);
            var aliquotaInss = hAPI.getCardValue("aliquotaInssCadastro___" + index);
            var reducaoInss = hAPI.getCardValue("reducaoInssCadastro___" + index);

            if (!codigoInss) {
                continue;
            }

            codigoInssCliente = codigoInss; 

            log.info("CODIGO INSS PARA CADASTRO -> " + codigoInss);
            log.info("DESCRICAO INSS PARA CADASTRO -> " + descricaoInss);
            log.info("ALIQUOTA INSS PARA CADASTRO -> " + aliquotaInss);
            log.info("REDUCAO INSS PARA CADASTRO -> " + reducaoInss);

            try {
                var authService = criarClienteRM();


                var xmlInss =
                    "<MovINSS>" +
                    "<TINSS>" +
                    "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
                    "<CODIGOINSS>" + codigoInss + "</CODIGOINSS>" +
                    "<DESCRICAO>" + descricaoInss + "</DESCRICAO>" +
                    "<ALIQUOTA>" + aliquotaInss + "</ALIQUOTA>" +
                    "<REDUCAOINSS>" + reducaoInss + "</REDUCAOINSS>" +
                    "</TINSS>" +
                    "</MovINSS>";

                var resultado = authService.saveRecord("MovINSSData", xmlInss, contexto);
                log.info("[G12-CADASTRO-DE-NOVO-INSS] Resultado: " + resultado);

            } catch (e) {
                log.error("[G12-CADASTRO-DE-NOVO-INSS] Erro: " + String(e));
                throw e;
            }
        }
    }


    if (!codigoIrrfCliente && !codigoInssCliente) {
        log.warn("[G12-CADASTRAR-IRRFeINSS] Nenhum IRRF/INSS novo encontrado. Abortando sincronizacao.");
        return;
    }

    try {
        var authService = criarClienteRM();

        var xmlPrdCfo =
            "<EstPrdCfoBR>" +
            "<TPrdCfo>" +
            "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
            "<IDPRD>" + idprd + "</IDPRD>" +
            "<CODCOLCFO>" + coligadaCliente + "</CODCOLCFO>" +
            "<CODCFO>" + codigoCliente + "</CODCFO>" +
            "<ATIVO>1</ATIVO>" +
            (codigoIrrfCliente ? "<CODIGOIRRF>" + codigoIrrfCliente + "</CODIGOIRRF>" : "") +
            (codigoInssCliente ? "<CODIGOINSS>" + codigoInssCliente + "</CODIGOINSS>" : "") +
            "</TPrdCfo>" +
            "</EstPrdCfoBR>";

        var resultado = authService.saveRecord("EstPrdCfoDataBR", xmlPrdCfo, contexto);
        log.info("[G12-SINCRONIZACAO IRRF/INSS NO PRODUTOxFORNECEDOR] Resultado: " + resultado);

    } catch (e) {
        log.error("[G12-ERRO SINCRONIZACAO IRRF/INSS NO PRODUTOxFORNECEDOR] Erro: " + String(e));
        throw e;
    }

    try {
        var c1 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);
        var c2 = DatasetFactory.createConstraint("IDMOV", idmovMovimento02, idmovMovimento02, ConstraintType.MUST);

        var dataset = DatasetFactory.getDataset("G12-CARREGAR-TRIBUTOS", null, [c1, c2], null);

        if (dataset == null || dataset.rowsCount == 0) {
            log.warn("[G12] Nenhum tributo retornado. CodColigada=" + codColigada + " IdMov2=" + idmovMovimento02);
            return;
        }

        hAPI.setCardValue('irrfDoItem', safe(dataset.getValue(0, "IRRF_DO_ITEM")));
        hAPI.setCardValue('irrfDescricao', safe(dataset.getValue(0, "IRRF_DESCRICAO")));
        hAPI.setCardValue('irrfAliquota', safe(dataset.getValue(0, "IRRF_ALIQUOTA")));
        hAPI.setCardValue('irrfTipoDePessoa', safe(dataset.getValue(0, "TIPO_DE_PESSOA")));
        hAPI.setCardValue('inssDescricao', safe(dataset.getValue(0, "INSS_DESCRICAO")));
        hAPI.setCardValue('inssAliquota', safe(dataset.getValue(0, "INSS_ALIQUOTA")));
        hAPI.setCardValue('inssDoItem', safe(dataset.getValue(0, "INSS_DO_ITEM")));

    } catch (e) {
        log.error("### Erro ao carregar tributos do dataset G12-CARREGAR-TRIBUTOS -> " + e);
        throw e;
    }
}

function servicetask78(attempt, message) {
    /**
     * AUTHOR: ENOS DESENVOLVEDOR FLUIG/FULL STACK 
     * CRIADO EM: 29/05/2026
     * PROPOSITO: FATURAR OS MOVIMENTOS DE VENDAS DO TIPO 2.1.02 , CRIAR MOVIMENTO 2.2.01 E GERAR O RELACIONAMENTO ENTRE ELES DENTRO DO RM 
    */



    var codColigada = hAPI.getCardValue("CodColigada");
    var idMov = hAPI.getCardValue("idmovContratos");
    var codFilial = hAPI.getCardValue("filial");
    var today = new java.text.SimpleDateFormat("yyyy-MM-dd").format(new java.util.Date());

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");

    try {

        /* 
        AQUI VAI ACONTECER A MÁGICA DA INTEGRACAO 
        1 - ServiceManager.getService("wsProcess")- > PRIMEIRO É NECESSÁRIO PEGAR O SERVICO QUE SERA RESPONSAVEL PELA INTEGRACAO DENTRO DO SEU FLUIG , EM PAIENL DE CONTROLE - SERVICOS 
        2 - instantiate() - > O SERVICO RESPOSAVEL POR INTEGRACOES MAIS COMPLEXAS DENTRO DO FLUIG É O WSPROCESS, TAMBÉM EXISTE O WSDATASERVER POREM ELE SERVE PARA CRUD MAIS SIMPLES, ALTERAR, EXCLUIR MOVIMENTOS, REALIZAR UPDATES ETCC
            COMO NESSE CASO É UMA OPERAÇÃO COMPLEXA QUE ENVOLVE RELACIONAMENTOS, FATURAMENTO, GERAÇÃO , TRANSFERENCIA DE DADOS ENTRE OS MOVIMENTOS ETC.. O WSPROCESS EXECUTA ISSO PERFEITAMENTE. 
        3 - IRÁ INSTANCIAR ESSE SERVICO , FAZER UMA ESPÉCIA DE CÓPIA DA CLASSE WSPROCESS (servico.instantiate("com.totvs.WsProcess"))
        4 - getRMIwsProcess() -> TEM ACESSO AOS METODOS DA CLASSE INTANCIADA 
        5 - properties -> INFORMACOES PARA AUTORIZACAO DO USO DO SERVICO DENTRO DO SERVIDOR DO RM, PRINCIPALMENTE O USUARIO E SENHA 
            E, INDISCUTIVELMENTE, UM TIMEOUT BOM, POIS, ISSO PODE IMPEDIR A EXECUSAO DA ATIVIDADE.
        6- getCustomClient() - > PASSAR AS INFORMACOES DE AUTORIZACOES E OS METODOS DA CLASSE INTANCIADA 
        7- executeWithParams() - > Metodo para faturar movimentos , passando o server name e o corpo XML -> executeWithParams("MovFaturamentoProc", xmlParams)

        */
        var servico = ServiceManager.getService("wsProcess");
        var instancia = servico.instantiate("com.totvs.WsProcess");
        var ws = instancia.getRMIwsProcess();
        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);

        log.info("### Servico OK, executando faturamento IDMOV=" + idMov);

        var xmlParams =
            '<MovFaturamentoProcParams>' +
            '<movCopiaFatPar>' +
            '<CodColigada>' + codColigada + '</CodColigada>' +
            '<CodSistema>T</CodSistema>' +
            '<CodTmvDestino>2.2.01</CodTmvDestino>' +
            '<CodTmvOrigem>2.1.02</CodTmvOrigem>' +
            '<CodUsuario>fluig</CodUsuario>' +
            '<GrupoFaturamento></GrupoFaturamento>' +
            '<IdExercicioFiscal>3</IdExercicioFiscal>' +
            '<IdMov>' +
            '<int>' + idMov + '</int>' +
            '</IdMov>' +
            '<TipoFaturamento>0</TipoFaturamento>' +
            '<dataBase>' + today + '</dataBase>' +
            '<dataEmissao/>' +
            '<dataSaida/>' +
            '<efeitoPedidoFatAutomatico>1</efeitoPedidoFatAutomatico>' +
            '<listaMovItemFatAutomatico/>' +
            '<numeroMov></numeroMov>' +
            '<realizaBaixaPedido>true</realizaBaixaPedido>' +
            '</movCopiaFatPar>' +
            '</MovFaturamentoProcParams>';

        var resp = authService.executeWithParams("MovFaturamentoProc", xmlParams);


    } catch (e) {
        log.error("### Erro: " + e);
        throw e;
    }



}


function getConstante(param) {
    var aConstraint = [];
    aConstraint.push(DatasetFactory.createConstraint('id', param, param, ConstraintType.MUST));
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

function servicetask87(attempt, message) {

    var codColigada = hAPI.getCardValue("CodColigada");
    var idmov = hAPI.getCardValue("idmov2");
    var codFilial = hAPI.getCardValue("filial") || "1";


    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");

    log.info("[G12-AjustarTributos] Iniciando - CODCOLIGADA=" + codColigada + " IDMOV=" + idmov);

    var tributosFormulario = {};
    var i = 1;

    while (true) {
        var sufixo = "___" + i;
        var codtrbN = hAPI.getCardValue("impostos_selecao" + sufixo);

        if (codtrbN == null || codtrbN == "" || codtrbN == "null" || codtrbN == undefined) break;

        var valorN = hAPI.getCardValue("valorImposto" + sufixo);
        var aliqN = hAPI.getCardValue("aliquota" + sufixo);
        var baseN = hAPI.getCardValue("baseCalculo" + sufixo);

        tributosFormulario[String(codtrbN).trim()] = {
            valor: valorN ? String(valorN).replace(",", ".") : "0.0000",
            aliquota: aliqN ? String(aliqN).replace(",", ".") : "0.0000",
            basecalculo: baseN ? String(baseN).replace(",", ".") : "0.0000"
        };

        log.info("[G12-AjustarTributos] Tributo do formulario: " + String(codtrbN).trim() + " = " + JSON.stringify(tributosFormulario[String(codtrbN).trim()]));

        i++;
        if (i > 50) break;
    }

    log.info("[G12-AjustarTributos] Total tributos formulario: " + Object.keys(tributosFormulario).length);

    if (Object.keys(tributosFormulario).length === 0) {
        log.warn("[G12-AjustarTributos] Nenhum tributo encontrado. Abortando.");
        return;
    }

    function formatarParaRM(valor) {
        return String(valor).replace(".", ",");
    }

    try {
        var servico = ServiceManager.getService("wsDataServer");
        var instancia = servico.instantiate("com.totvs.WsDataServer");
        var ws = instancia.getRMIwsDataServer();

        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);
        var contexto = "CODCOLIGADA=" + codColigada + ";CODFILIAL=" + codFilial + ";CODSISTEMA=T;CODUSUARIO=fluig";

        log.info("[G12-AjustarTributos] Fazendo ReadRecord...");
        var xmlAtual = authService.readRecord("MovMovimentoTBCData", codColigada + ";" + idmov, contexto);
        log.info("[G12-AjustarTributos] ReadRecord OK");

        var xmlStr = String(xmlAtual);
        var xmlTributos = "";

        function extrair(tag, texto) {
            var r = new RegExp("<" + tag + ">([^<]*)<\\/" + tag + ">");
            var m = r.exec(texto);
            return m ? m[1].trim() : "";
        }

        var regexBloco = /<TTRBITMMOV>([\s\S]*?)<\/TTRBITMMOV>/g;
        var match;

        while ((match = regexBloco.exec(xmlStr)) !== null) {
            var bloco = match[1];

            var codtrb = extrair("CODTRB", bloco);
            var basecalculo = extrair("BASEDECALCULO", bloco);
            var aliquota = extrair("ALIQUOTA", bloco);
            var valor = extrair("VALOR", bloco);
            var editado = extrair("EDITADO", bloco) || "0";
            var tiporecolh = extrair("TIPORECOLHIMENTO", bloco);
            var extras = tiporecolh ? "<TIPORECOLHIMENTO>" + tiporecolh + "</TIPORECOLHIMENTO>" : "";

            log.info("[G12-AjustarTributos] Tributo lido: " + codtrb + " base=" + basecalculo + " aliq=" + aliquota + " valor=" + valor);

            if (tributosFormulario[codtrb]) {
                basecalculo = tributosFormulario[codtrb].basecalculo;
                aliquota = tributosFormulario[codtrb].aliquota;
                valor = tributosFormulario[codtrb].valor;
                editado = "1";
                log.info("[G12-AjustarTributos] Atualizando tributo: " + codtrb);
            }

            xmlTributos +=
                "<TTRBITMMOV>" +
                "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
                "<IDMOV>" + idmov + "</IDMOV>" +
                "<NSEQITMMOV>1</NSEQITMMOV>" +
                "<CODTRB>" + codtrb + "</CODTRB>" +
                "<BASEDECALCULO>" + formatarParaRM(basecalculo) + "</BASEDECALCULO>" +
                "<ALIQUOTA>" + formatarParaRM(aliquota) + "</ALIQUOTA>" +
                "<VALOR>" + formatarParaRM(valor) + "</VALOR>" +
                "<EDITADO>" + editado + "</EDITADO>" +
                extras +
                "</TTRBITMMOV>";
        }

        log.info("[G12-AjustarTributos] xmlTributos montado: " + xmlTributos);

        var xmlFinal =
            "<MovMovimento>" +
            "<TMOV>" +
            "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
            "<IDMOV>" + idmov + "</IDMOV>" +
            "<INTEGRAAPLICACAO>T</INTEGRAAPLICACAO>" +
            "</TMOV>" +
            xmlTributos +
            "</MovMovimento>";

        var resultado = authService.saveRecord("MovMovimentoTBCData", xmlFinal, contexto);
        log.info("[G12-AjustarTributos] Resultado SaveRecord: " + resultado);

    } catch (e) {
        log.error("[G12-AjustarTributos] Erro: " + String(e));
        throw e;
    }


    try {

        var c1 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);
        var c2 = DatasetFactory.createConstraint("IDMOV", idmov, idmov, ConstraintType.MUST);

        var dataset = DatasetFactory.getDataset("G12-CARREGAR-TRIBUTOS", null, [c1, c2], null);


        if (dataset == null || dataset.rowsCount == 0) {
            log.warn("[G12] Nenhum tributo retornado. CodColigada=" + codColigada + " IdMov2=" + idmov);
            return;
        }


        hAPI.setCardValue('tributosNacionais', safe(dataset.getValue(0, "TRIBUTOS_NACIONAIS")));
        hAPI.setCardValue('naturezaOrcamentaria', safe(dataset.getValue(0, "NATUREZA_ORCAMENTARIA")));
        hAPI.setCardValue('irrfDoItem', safe(dataset.getValue(0, "IRRF_DO_ITEM")));
        hAPI.setCardValue('inssDoItem', safe(dataset.getValue(0, "INSS_DO_ITEM")));
        hAPI.setCardValue('tributosMunicipais', safe(dataset.getValue(0, "TRIBUTOS_MUNICIPAIS")));


    } catch (e) {
        log.error("### Erro ao carregar impostos nacionais e municipias do dataset ->  " + e);
        throw e;
    }

}

function getConstante(param) {
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

