function safe(valor) {
    log.info("VALOR DO IDMOV QUE ENTROU DENTRO DO CAMPO DE VALIDACAO DE CARREGAMENTO" + valor)
    if (valor == null || valor == undefined) return "";
    var s = String(valor).trim();
    return (s == "null" || s == "undefined") ? "" : s;
}

